const int numColours = 8;

const int nodesToMix = 2; // dither only supports blending 2 at the moment

struct VoronoiSample
{
    // 0 = nearest, 1 = 2nd nearest
    vec3 pos[nodesToMix];
    float weight[nodesToMix];
};

VoronoiSample Voronoi( vec3 pos )
{
    vec3 closestPos[nodesToMix+1];
    float closestDist[nodesToMix+1];

    for ( int node=0; node < nodesToMix+1; node++ )
    {
        closestPos[node] = vec3(0);
        closestDist[node] = 1e38;
    }

    for ( int i=0; i < numColours; i++ )
    {
        vec3 nodePos = texelFetch(iChannel1,(ivec2(i,8)+ivec2(iMouse.x,iMouse.y))%ivec2(iChannelResolution[1].xy),0).rgb;

        // map generated colours into more visually appealling values
        nodePos = pow(nodePos,vec3(2.2));
        nodePos = clamp((nodePos-.5)*1.2+.5,0.,1.);

        bool inserted = false;
        vec3 copyPos;
        float copyDist;
        for ( int node=0; node < nodesToMix+1; node++ )
        {
            if ( !inserted && length(pos-nodePos) < closestDist[node] )
            {
                inserted = true;
                copyPos = nodePos;
                copyDist = length(pos-nodePos);
            }

            if ( inserted )
            {
                vec3 newPos = closestPos[node];
                closestPos[node] = copyPos;
                copyPos = newPos;

                float newDist = closestDist[node];
                closestDist[node] = copyDist;
                copyDist = newDist;
            }
        }
    }

    // now result[0] is closest node, result[1] is second closest, etc
    // compute weights that add to 1.0 and which fade out the influence of the last weight

    VoronoiSample result;
    float totalWeight = 0.;
    for ( int node=0; node < nodesToMix; node++ )
    {
        result.pos[node] = closestPos[node];
        result.weight[node] = closestDist[nodesToMix]-closestDist[node]; //pretty sure this is wrong
        totalWeight += result.weight[node];
    }

    for ( int node=0; node < nodesToMix; node++ )
    {
        result.weight[node] /= totalWeight;
    }

    return result;
}

void mainImage( out vec4 fragColour, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    fragColour = texture(iChannel0,uv);
    fragColour.rgb = pow(fragColour.rgb,vec3(2.2));

    // debug - test voronoi works
//    VoronoiSample result = Voronoi(vec3(uv,.5));
//    fragColour.rgb = result.pos[0]*result.weight[0] + result.pos[1]*result.weight[1];

    // find the 2 closest colours in the palette
    VoronoiSample palette = Voronoi(fragColour.rgb);

    float dither = texelFetch(iChannel2,ivec2(fragCoord)%ivec2(iChannelResolution[2].xy),0).r;
    fragColour.rgb = mix( palette.pos[0], palette.pos[1], step(dither,palette.weight[0]) );

    fragColour.rgb = pow(fragColour.rgb,vec3(1./2.2));
}
